  'frontend.public_rest_booking_is_disabled_use_the_site_booking_form_or_enable_pu' => 
  array (
    'group' => 'frontend',
    'label' => 'Public REST booking is disabled. Use the site booking form or enable public R...',
    'default' => 'Public REST booking is disabled. Use the site booking form or enable public REST booking in Slotera security settings.',
    'mt_MT' => 'Il-prenotazzjoni REST pubblika hija diżattivata. Uża l-formola tal-prenotazzjoni tas-sit jew attiva l-prenotazzjoni REST pubblika fis-settings tas-sigurtà ta’ Slotera.',
    'de_DE' => 'Öffentliche REST-Buchung ist deaktiviert. Verwenden Sie das Buchungsformular der Website oder aktivieren Sie die öffentliche REST-Buchung in den Slotera-Sicherheitseinstellungen.',
    'nl_NL' => 'Openbare REST-boeking is uitgeschakeld. Gebruik het boekingsformulier op de site of schakel openbare REST-boeking in de Slotera-beveiligingsinstellingen in.',
    'pl_PL' => 'Publiczna rezerwacja REST jest wyłączona. Użyj formularza rezerwacji na stronie albo włącz publiczną rezerwację REST w ustawieniach zabezpieczeń Slotera.',
    'lt_LT' => 'Viešas REST užsakymas išjungtas. Naudokite svetainės užsakymo formą arba įjunkite viešą REST užsakymą Slotera saugos nustatymuose.',
    'lv' => 'Publiskā REST rezervēšana ir atspējota. Izmantojiet vietnes rezervācijas formu vai iespējojiet publisko REST rezervēšanu Slotera drošības iestatījumos.',
    'bg_BG' => 'Публичното REST резервиране е изключено. Използвайте формата за резервация в сайта или активирайте публичното REST резервиране в настройките за сигурност на Slotera.',
    'et' => 'Avalik REST-broneerimine on keelatud. Kasuta saidi broneerimisvormi või luba avalik REST-broneerimine Slotera turvaseadetes.',
    'fr_FR' => 'La réservation publique via REST est désactivée. Utilisez le formulaire de réservation du site ou activez la réservation publique via REST dans les réglages de sécurité de Slotera.',
    'it_IT' => 'La prenotazione REST pubblica è disabilitata. Utilizza il modulo di prenotazione del sito oppure abilita la prenotazione REST pubblica nelle impostazioni di sicurezza di Slotera.',
    'es_ES' => 'Las reservas mediante REST público están desactivadas. Usa el formulario de reservas del sitio o activa las reservas REST públicas en los ajustes de seguridad de Slotera.',
    'ru_RU' => 'Публичное REST-бронирование отключено. Используйте форму бронирования на сайте или включите публичное REST-бронирование в настройках безопасности Slotera.',
    'pt_PT' => 'As marcações através da API pública estão desativadas. Utilize o formulário de marcação da página ou ative esta opção nas definições de segurança do Slotera.',
    'pt_BR' => 'As reservas pela API pública estão desativadas. Utilize o formulário de reservas da página ou habilite essa opção nas configurações de segurança do Slotera.',
    'ro_RO' => 'Rezervarea publică REST este dezactivată. Folosiți formularul de rezervare al site-ului sau activați rezervarea publică REST în setările de securitate Slotera.',
    'sv_SE' => 'Offentlig REST-bokning är inaktiverad. Använd bokningsformuläret på webbplatsen eller aktivera offentlig REST-bokning i Slotera-säkerhetsinställningarna.',
    'da_DK' => 'Offentlig REST-booking er deaktiveret. Brug bookingformularen på siden eller aktiver offentlig REST-booking i Slotera-sikkerhedsindstillingerne.',
    'fi' => 'Julkinen REST-varaus on poistettu käytöstä. Käytä sivuston varauslomaketta tai ota julkinen REST-varaus käyttöön Sloteran turvallisuusasetuksissa.',
    'cs_CZ' => 'Veřejná REST rezervace je vypnutá. Použijte rezervační formulář na webu nebo povolte veřejnou REST rezervaci v nastavení zabezpečení Slotera.',
    'cs' => 'Veřejná REST rezervace je vypnutá. Použijte rezervační formulář na webu nebo povolte veřejnou REST rezervaci v nastavení zabezpečení Slotera.',
    'sk_SK' => 'Veřejná REST rezervace je vypnutá. Použijte rezervační formulář na webu nebo povolte veřejnou REST rezervaci v nastavení zabezpečení Slotera.',
    'sk' => 'Veřejná REST rezervace je vypnutá. Použijte rezervační formulář na webu nebo povolte veřejnou REST rezervaci v nastavení zabezpečení Slotera.',
    'hu_HU' => 'A nyilvános REST foglalás ki van kapcsolva. Használja a webhely foglalási űrlapját, vagy engedélyezze a nyilvános REST foglalást a Slotera biztonsági beállításaiban.',
    'hu' => 'A nyilvános REST foglalás ki van kapcsolva. Használja a webhely foglalási űrlapját, vagy engedélyezze a nyilvános REST foglalást a Slotera biztonsági beállításaiban.',
    'el_GR' => 'Η δημόσια κράτηση REST είναι απενεργοποιημένη. Χρησιμοποιήστε τη φόρμα κράτησης του ιστότοπου ή ενεργοποιήστε τη δημόσια REST κράτηση στις ρυθμίσεις ασφαλείας του Slotera.',
    'el' => 'Η δημόσια κράτηση REST είναι απενεργοποιημένη. Χρησιμοποιήστε τη φόρμα κράτησης του ιστότοπου ή ενεργοποιήστε τη δημόσια REST κράτηση στις ρυθμίσεις ασφαλείας του Slotera.',
    'hr' => 'Javna REST rezervacija je onemogućena. Koristite obrazac za rezervaciju na stranici ili omogućite javnu REST rezervaciju u sigurnosnim postavkama Slotera.',
    'hr_HR' => 'Javna REST rezervacija je onemogućena. Koristite obrazac za rezervaciju na stranici ili omogućite javnu REST rezervaciju u sigurnosnim postavkama Slotera.',
    'sl_SI' => 'Javna REST rezervacija je onemogočena. Uporabite obrazec za rezervacijo na spletnem mestu ali omogočite javno REST rezervacijo v varnostnih nastavitvah Slotera.',
    'sl' => 'Javna REST rezervacija je onemogočena. Uporabite obrazec za rezervacijo na spletnem mestu ali omogočite javno REST rezervacijo v varnostnih nastavitvah Slotera.',
