  'frontend.please_confirm_that_you_want_to_cancel_this_booking_this_action_will_n' => 
  array (
    'group' => 'frontend',
    'label' => 'Please confirm that you want to cancel this booking. This action will notify ...',
    'default' => 'Please confirm that you want to cancel this booking. This action will notify the site owner and customer if email notifications are enabled.',
    'mt_MT' => 'Ikkonferma li trid tikkanċella din il-prenotazzjoni. Din l-azzjoni tinnotifika lis-sid tas-sit u lill-klijent jekk in-notifiki bl-email huma attivati.',
    'de_DE' => 'Bitte bestätigen Sie, dass Sie diese Buchung stornieren möchten. Diese Aktion benachrichtigt den Websitebetreiber und den Kunden, wenn E-Mail-Benachrichtigungen aktiviert sind.',
    'nl_NL' => 'Bevestig dat je deze boeking wilt annuleren. Deze actie informeert de site-eigenaar en de klant als e-mailmeldingen zijn ingeschakeld.',
    'pl_PL' => 'Potwierdź, że chcesz anulować tę rezerwację. Ta akcja powiadomi właściciela strony i klienta, jeśli powiadomienia e-mail są włączone.',
    'lt_LT' => 'Patvirtinkite, kad norite atšaukti šį užsakymą. Jei el. pašto pranešimai įjungti, bus informuotas svetainės savininkas ir klientas.',
    'lv' => 'Lūdzu, apstipriniet, ka vēlaties atcelt šo rezervāciju. Ja e-pasta paziņojumi ir iespējoti, tiks informēts vietnes īpašnieks un klients.',
    'bg_BG' => 'Моля, потвърдете, че искате да отмените тази резервация. Това действие ще уведоми собственика на сайта и клиента, ако имейл известията са включени.',
    'et' => 'Palun kinnita, et soovid selle broneeringu tühistada. Kui e-posti teavitused on lubatud, teavitatakse saidi omanikku ja klienti.',
    'fr_FR' => 'Confirmez que vous souhaitez annuler cette réservation. Cette action avertira le propriétaire du site et le client si les notifications par e-mail sont activées.',
    'it_IT' => 'Conferma di voler annullare questa prenotazione. L’azione informerà il proprietario del sito e il cliente se le notifiche email sono abilitate.',
    'es_ES' => 'Confirma que deseas cancelar esta reserva. Esta acción notificará al propietario del sitio y al cliente si las notificaciones por correo están activadas.',
    'ru_RU' => 'Подтвердите, что хотите отменить это бронирование. Если email-уведомления включены, владелец сайта и клиент получат уведомление.',
    'pt_PT' => 'Confirme que deseja cancelar esta reserva. Esta ação notificará o proprietário do site e o cliente se as notificações por email estiverem ativadas.',
    'pt_BR' => 'Confirme que deseja cancelar esta reserva. Esta ação notificará o proprietário do site e o cliente se as notificações por email estiverem ativadas.',
    'ro_RO' => 'Confirmați că doriți să anulați această rezervare. Acțiunea va notifica proprietarul site-ului și clientul dacă notificările prin e-mail sunt activate.',
    'sv_SE' => 'Bekräfta att du vill avboka denna bokning. Denna åtgärd meddelar webbplatsägaren och kunden om e-postaviseringar är aktiverade.',
    'da_DK' => 'Bekræft, at du vil afbestille denne booking. Denne handling giver besked til sideejeren og kunden, hvis e-mailnotifikationer er aktiveret.',
    'fi' => 'Vahvista, että haluat peruuttaa tämän varauksen. Toiminto ilmoittaa sivuston omistajalle ja asiakkaalle, jos sähköposti-ilmoitukset ovat käytössä.',
    'cs_CZ' => 'Potvrďte prosím, že chcete tuto rezervaci zrušit. Pokud jsou zapnutá e-mailová oznámení, bude informován majitel webu i zákazník.',
    'cs' => 'Potvrďte prosím, že chcete tuto rezervaci zrušit. Pokud jsou zapnutá e-mailová oznámení, bude informován majitel webu i zákazník.',
    'sk_SK' => 'Potvrďte, že chcete zrušiť túto rezerváciu. Ak sú e-mailové oznámenia zapnuté, upozornenie bude odoslané vlastníkovi webovej stránky aj zákazníkovi.',
    'sk' => 'Potvrďte, že chcete zrušiť túto rezerváciu. Ak sú e-mailové oznámenia zapnuté, upozornenie bude odoslané vlastníkovi webovej stránky aj zákazníkovi.',
    'hu_HU' => 'Kérjük, erősítse meg, hogy le szeretné mondani ezt a foglalást. Ha az e-mail értesítések engedélyezve vannak, a webhely tulajdonosa és az ügyfél értesítést kap.',
    'hu' => 'Kérjük, erősítse meg, hogy le szeretné mondani ezt a foglalást. Ha az e-mail értesítések engedélyezve vannak, a webhely tulajdonosa és az ügyfél értesítést kap.',
    'el_GR' => 'Επιβεβαιώστε ότι θέλετε να ακυρώσετε αυτήν την κράτηση. Αυτή η ενέργεια θα ειδοποιήσει τον ιδιοκτήτη του ιστότοπου και τον πελάτη αν είναι ενεργές οι ειδοποιήσεις email.',
    'el' => 'Επιβεβαιώστε ότι θέλετε να ακυρώσετε αυτήν την κράτηση. Αυτή η ενέργεια θα ειδοποιήσει τον ιδιοκτήτη του ιστότοπου και τον πελάτη αν είναι ενεργές οι ειδοποιήσεις email.',
    'hr' => 'Potvrdite da želite otkazati ovu rezervaciju. Ova će radnja obavijestiti vlasnika stranice i korisnika ako su obavijesti e-poštom omogućene.',
    'hr_HR' => 'Potvrdite da želite otkazati ovu rezervaciju. Ova će radnja obavijestiti vlasnika stranice i korisnika ako su obavijesti e-poštom omogućene.',
    'sl_SI' => 'Potrdite, da želite odpovedati to rezervacijo. To dejanje bo obvestilo lastnika spletnega mesta in stranko, če so e-poštna obvestila omogočena.',
    'sl' => 'Potrdite, da želite odpovedati to rezervacijo. To dejanje bo obvestilo lastnika spletnega mesta in stranko, če so e-poštna obvestila omogočena.',
    'no_NO' => 'Bekreft at du vil avbestille denne bestillingen. Denne handlingen varsler nettstedseieren og kunden hvis e-postvarsler er aktivert.',
    'no' => 'Bekreft at du vil avbestille denne bestillingen. Denne handlingen varsler nettstedseieren og kunden hvis e-postvarsler er aktivert.',
    'nb_NO' => 'Bekreft at du vil avbestille denne bestillingen. Denne handlingen varsler nettstedseieren og kunden hvis e-postvarsler er aktivert.',
    'nb' => 'Bekreft at du vil avbestille denne bestillingen. Denne handlingen varsler nettstedseieren og kunden hvis e-postvarsler er aktivert.',
    'is_IS' => 'Staðfestu að þú viljir afbóka þessa bókun. Þessi aðgerð lætur eiganda síðunnar og viðskiptavin vita ef tölvupósttilkynningar eru virkar.',
    'is' => 'Staðfestu að þú viljir afbóka þessa bókun. Þessi aðgerð lætur eiganda síðunnar og viðskiptavin vita ef tölvupósttilkynningar eru virkar.',
    'ga' => 'Deimhnigh gur mian leat an áirithint seo a chealú. Cuirfidh an gníomh seo úinéir an tsuímh agus an custaiméir ar an eolas má tá fógraí ríomhphoist cumasaithe.',
    'ga_IE' => 'Deimhnigh gur mian leat an áirithint seo a chealú. Cuirfidh an gníomh seo úinéir an tsuímh agus an custaiméir ar an eolas má tá fógraí ríomhphoist cumasaithe.',
    'textarea' => true,
  ),
