    'fr_FR' => 'Connectez-vous à l’aide d’un lien sécurisé reçu par e-mail pour consulter l’historique de vos réservations et gérer celles à venir.',
    'it_IT' => 'Accedi tramite un link email sicuro per visualizzare la cronologia e gestire le prossime prenotazioni.',
    'es_ES' => 'Inicia sesión con un enlace seguro enviado por correo para ver tu historial de reservas y gestionar las próximas reservas.',
    'ru_RU' => 'Войдите через безопасную ссылку из email, чтобы просматривать историю бронирований и управлять предстоящими бронированиями.',
    'pt_PT' => 'Inicie sessão com um link seguro por email para ver o histórico de reservas e gerir reservas futuras.',
    'pt_BR' => 'Inicie sessão com um link seguro por email para ver o histórico de reservas e gerir reservas futuras.',
    'ro_RO' => 'Autentificați-vă cu un link sigur prin e-mail pentru a vedea istoricul rezervărilor și a gestiona rezervările viitoare.',
    'sv_SE' => 'Logga in med en säker e-postlänk för att se din bokningshistorik och hantera kommande bokningar.',
    'da_DK' => 'Log ind med et sikkert e-mail-link for at se din bookinghistorik og administrere kommende bookinger.',
    'fi' => 'Kirjaudu sisään turvallisella sähköpostilinkillä nähdäksesi varaushistoriasi ja hallitaksesi tulevia varauksia.',
    'cs_CZ' => 'Přihlaste se pomocí bezpečného e-mailového odkazu, abyste viděli historii rezervací a mohli spravovat nadcházející rezervace.',
    'cs' => 'Přihlaste se pomocí bezpečného e-mailového odkazu, abyste viděli historii rezervací a mohli spravovat nadcházející rezervace.',
    'sk_SK' => 'Přihlaste se pomocí bezpečného e-mailového odkazu, abyste viděli historii rezervací a mohli spravovat nadcházející rezervace.',
    'sk' => 'Přihlaste se pomocí bezpečného e-mailového odkazu, abyste viděli historii rezervací a mohli spravovat nadcházející rezervace.',
    'hu_HU' => 'Jelentkezzen be biztonságos e-mail linken keresztül a foglalási előzmények megtekintéséhez és a közelgő foglalások kezeléséhez.',
    'hu' => 'Jelentkezzen be biztonságos e-mail linken keresztül a foglalási előzmények megtekintéséhez és a közelgő foglalások kezeléséhez.',
    'el_GR' => 'Συνδεθείτε με ασφαλή σύνδεσμο email για να δείτε το ιστορικό κρατήσεων και να διαχειριστείτε επερχόμενες κρατήσεις.',
    'el' => 'Συνδεθείτε με ασφαλή σύνδεσμο email για να δείτε το ιστορικό κρατήσεων και να διαχειριστείτε επερχόμενες κρατήσεις.',
    'hr' => 'Prijavite se sigurnom poveznicom e-pošte za pregled povijesti rezervacija i upravljanje nadolazećim rezervacijama.',
    'hr_HR' => 'Prijavite se sigurnom poveznicom e-pošte za pregled povijesti rezervacija i upravljanje nadolazećim rezervacijama.',
    'sl_SI' => 'Prijavite se z varno email povezavo za ogled zgodovine rezervacij in upravljanje prihajajočih rezervacij.',
    'sl' => 'Prijavite se z varno email povezavo za ogled zgodovine rezervacij in upravljanje prihajajočih rezervacij.',
    'no_NO' => 'Logg inn med en sikker e-postlenke for å se bestillingshistorikken og administrere kommende bestillinger.',
    'no' => 'Logg inn med en sikker e-postlenke for å se bestillingshistorikken og administrere kommende bestillinger.',
