  'frontend.click_the_button_below_to_sign_in_to_your_booking_account_this_extra_conf' => 
  array (
    'group' => 'frontend',
    'label' => 'Click the button below to sign in to your booking account. This extra confirmation...',
    'default' => 'Click the button below to sign in to your booking account. This extra confirmation keeps email security scanners from using your one-time link before you do.',
    'mt_MT' => 'Ikklikkja l-buttuna hawn taħt biex tidħol fil-kont tal-prenotazzjonijiet tiegħek. Din il-konferma addizzjonali tipprevjeni lill-iskanners tas-sigurtà tal-email milli jużaw il-link ta’ darba qablek.',
    'el_GR' => 'Κάντε κλικ στο παρακάτω κουμπί για να συνδεθείτε στον λογαριασμό κρατήσεών σας. Αυτή η πρόσθετη επιβεβαίωση εμποδίζει τους σαρωτές ασφαλείας email να χρησιμοποιήσουν τον σύνδεσμο μίας χρήσης πριν από εσάς.',
    'el' => 'Κάντε κλικ στο παρακάτω κουμπί για να συνδεθείτε στον λογαριασμό κρατήσεών σας. Αυτή η πρόσθετη επιβεβαίωση εμποδίζει τους σαρωτές ασφαλείας email να χρησιμοποιήσουν τον σύνδεσμο μίας χρήσης πριν από εσάς.',
    'is_IS' => 'Smelltu á hnappinn hér að neðan til að skrá þig inn á bókunarreikninginn þinn. Þessi aukastaðfesting kemur í veg fyrir að öryggisskannar tölvupósts noti einskiptistengilinn áður en þú gerir það.',
    'is' => 'Smelltu á hnappinn hér að neðan til að skrá þig inn á bókunarreikninginn þinn. Þessi aukastaðfesting kemur í veg fyrir að öryggisskannar tölvupósts noti einskiptistengilinn áður en þú gerir það.',
    'en_US' => 'Click the button below to sign in to your booking account. This extra confirmation keeps email security scanners from using your one-time link before you do.',
    'et' => 'Broneeringukontole sisselogimiseks klõpsake alloleval nupul. See lisakinnitus takistab e-posti turvaskanneritel ühekordset linki enne teid kasutamast.',
    'ru_RU' => 'Нажмите кнопку ниже, чтобы войти в аккаунт бронирований. Это дополнительное подтверждение не даёт почтовым сканерам безопасности использовать одноразовую ссылку раньше вас.',
    'textarea' => true,
    'de_DE' => 'Klicken Sie auf die Schaltfläche unten, um sich bei Ihrem Buchungskonto anzumelden. Diese zusätzliche Bestätigung verhindert, dass E-Mail-Sicherheitsscanner Ihren Einmal-Link vor Ihnen verwenden.',
    'fi' => 'Kirjaudu varaustilillesi napsauttamalla alla olevaa painiketta. Lisävahvistus estää sähköpostin tietoturvaskannereita käyttämästä kertakäyttölinkkiä ennen sinua.',
    'fr_FR' => 'Cliquez sur le bouton ci-dessous pour vous connecter à votre compte de réservation. Cette confirmation supplémentaire empêche les scanners de sécurité des e-mails d’utiliser votre lien à usage unique avant vous.',
    'sv_SE' => 'Klicka på knappen nedan för att logga in på ditt bokningskonto. Den extra bekräftelsen hindrar säkerhetsskannrar för e-post från att använda din engångslänk före dig.',
    'da_DK' => 'Klik på knappen nedenfor for at logge ind på din bookingkonto. Den ekstra bekræftelse forhindrer e-mailsikkerhedsscannere i at bruge dit engangslink før dig.',
    'nl_NL' => 'Klik op de onderstaande knop om in te loggen op uw boekingsaccount. Deze extra bevestiging voorkomt dat beveiligingsscanners voor e-mail uw eenmalige link gebruiken voordat u dat doet.',
    'es_ES' => 'Haz clic en el botón de abajo para iniciar sesión en tu cuenta de reservas. Esta confirmación adicional evita que los analizadores de seguridad del correo utilicen tu enlace de un solo uso antes que tú.',
    'it_IT' => 'Fai clic sul pulsante qui sotto per accedere al tuo account di prenotazione. Questa conferma aggiuntiva impedisce agli scanner di sicurezza email di utilizzare il link monouso prima di te.',
    'pt_PT' => 'Clique no botão abaixo para iniciar sessão na sua conta de reservas. Esta confirmação adicional...',
    'pt_BR' => 'Clique no botão abaixo para entrar na sua conta de reservas. Essa confirmação adicional impede que scanners de segurança de e-mail usem seu link de uso único antes de você.',
    'pl_PL' => 'Kliknij przycisk poniżej, aby zalogować się na konto rezerwacji. To dodatkowe potwierdzenie zapobiega użyciu jednorazowego linku przez skanery bezpieczeństwa poczty przed Tobą.',
    'cs_CZ' => 'Kliknutím na tlačítko níže se přihlaste ke svému rezervačnímu účtu. Toto dodatečné potvrzení zabrání bezpečnostním skenerům e-mailu použít váš jednorázový odkaz dříve než vy.',
    'cs' => 'Kliknutím na tlačítko níže se přihlaste ke svému rezervačnímu účtu. Toto dodatečné potvrzení zabrání bezpečnostním skenerům e-mailu použít váš jednorázový odkaz dříve než vy.',
    'sk_SK' => 'Kliknutím na tlačidlo nižšie sa prihláste do svojho rezervačného účtu. Toto dodatočné potvrdenie zabráni bezpečnostným skenerom e-mailov použiť váš jednorazový odkaz skôr než vy.',
    'sl_SI' => 'Kliknite spodnji gumb, da se prijavite v svoj račun za rezervacije. Ta dodatna potrditev preprečuje, da bi varnostni pregledovalniki e-pošte uporabili vašo enkratno povezavo pred vami.',
    'hr' => 'Kliknite gumb u nastavku kako biste se prijavili na svoj račun za rezervacije. Ova dodatna potvrda sprječava sigurnosne skenere e-pošte da iskoriste jednokratnu poveznicu prije vas.',
    'hr_HR' => 'Kliknite gumb u nastavku kako biste se prijavili na svoj račun za rezervacije. Ova dodatna potvrda sprječava sigurnosne skenere e-pošte da iskoriste jednokratnu poveznicu prije vas.',
    'ro_RO' => 'Faceți clic pe butonul de mai jos pentru a vă autentifica în contul de rezervări. Această confirmare suplimentară împiedică scanerele de securitate ale e-mailului să utilizeze linkul unic înaintea dvs.',
    'hu_HU' => 'Az alábbi gombra kattintva jelentkezzen be foglalási fiókjába. Ez a kiegészítő megerősítés megakadályozza, hogy az e-mail-biztonsági ellenőrzők Ön előtt használják fel az egyszer használatos hivatkozást.',
    'hu' => 'Az alábbi gombra kattintva jelentkezzen be foglalási fiókjába. Ez a kiegészítő megerősítés megakadályozza, hogy az e-mail-biztonsági ellenőrzők Ön előtt használják fel az egyszer használatos hivatkozást.',
    'bg_BG' => 'Натиснете бутона по-долу, за да влезете в профила си за резервации. Това допълнително потвърждение не позволява на скенерите за сигурност на имейла да използват еднократната ви връзка преди вас.',
    'lt_LT' => 'Spustelėkite toliau esantį mygtuką, kad prisijungtumėte prie rezervacijų paskyros. Šis papildomas patvirtinimas neleidžia el. pašto saugos skaitytuvams panaudoti vienkartinės nuorodos anksčiau už jus.',
    'no_NO' => 'Klikk på knappen nedenfor for å logge inn på bestillingskontoen din. Denne ekstra bekreftelsen hindrer sikkerhetsskannere for e-post i å bruke engangslenken før deg.',
    'lv' => 'Noklikšķiniet uz zemāk esošās pogas, lai pieteiktos savā rezervāciju kontā. Šis papildu apstiprinājums neļauj e-pasta drošības skeneriem izmantot vienreizējo saiti pirms jums.',
    'ga_IE' => 'Cliceáil an cnaipe thíos chun logáil isteach i do chuntas áirithinte. Cuireann an deimhniú breise seo cosc ar scanóirí slándála ríomhphoist do nasc aonuaire a úsáid sula n-úsáideann tú féin é.',
  ),
