  'frontend.did_not_receive_it_check_spam_first_then_use_the_resend_button_above_f' => 
  array (
    'group' => 'frontend',
    'label' => 'Did not receive it? Check spam first, then use the resend button above. For s...',
    'default' => 'Did not receive it? Check spam first, then use the resend button above. For security, requests are rate-limited.',
    'mt_MT' => 'Ma rċevejtux? Iċċekkja l-ispam l-ewwel, imbagħad uża l-buttuna biex terġa’ tibgħat hawn fuq. Għas-sigurtà, it-talbiet huma limitati.',
    'de_DE' => 'Nicht erhalten? Prüfen Sie zuerst den Spam-Ordner und verwenden Sie dann die Schaltfläche zum erneuten Senden. Aus Sicherheitsgründen sind Anfragen begrenzt.',
    'nl_NL' => 'Niet ontvangen? Controleer eerst spam en gebruik daarna de knop hierboven om opnieuw te verzenden. Om veiligheidsredenen zijn aanvragen beperkt.',
    'pl_PL' => 'Nie otrzymano? Najpierw sprawdź spam, a potem użyj przycisku ponownej wysyłki powyżej. Ze względów bezpieczeństwa liczba żądań jest ograniczona.',
    'lt_LT' => 'Negavote? Pirmiausia patikrinkite šlamštą, tada naudokite aukščiau esantį pakartotinio siuntimo mygtuką. Saugumo sumetimais užklausos ribojamos.',
    'lv' => 'Nesaņēmāt? Vispirms pārbaudiet mēstules, pēc tam izmantojiet augstāk esošo atkārtotas nosūtīšanas pogu. Drošības nolūkos pieprasījumi ir ierobežoti.',
    'bg_BG' => 'Не го получихте? Първо проверете спам папката, след това използвайте бутона за повторно изпращане. За сигурност заявките са ограничени.',
    'et' => 'Ei saanud kätte? Kontrolli esmalt rämpsposti ja kasuta seejärel ülal olevat uuesti saatmise nuppu. Turvalisuse huvides on päringud piiratud.',
    'fr_FR' => 'Vous ne l’avez pas reçu ? Vérifiez d’abord les courriers indésirables, puis utilisez le bouton de renvoi ci-dessus. Pour des raisons de sécurité, le nombre de demandes est limité.',
    'it_IT' => 'Non l’hai ricevuto? Controlla prima lo spam, quindi usa il pulsante qui sopra per inviarlo di nuovo. Per sicurezza, le richieste sono soggette a limite di frequenza.',
    'es_ES' => '¿No lo has recibido? Comprueba primero la carpeta de spam y después usa el botón de reenvío de arriba. Por seguridad, las solicitudes tienen un límite de frecuencia.',
    'ru_RU' => 'Не получили письмо? Сначала проверьте спам, затем используйте кнопку повторной отправки выше. В целях безопасности количество запросов ограничено.',
    'pt_PT' => 'Não recebeu? Verifique primeiro o spam e use o botão de reenviar acima. Por segurança, os pedidos são limitados.',
    'pt_BR' => 'Não recebeu? Verifique primeiro o spam e use o botão de reenviar acima. Por segurança, os pedidos são limitados.',
    'ro_RO' => 'Nu l-ați primit? Verificați mai întâi spamul, apoi folosiți butonul de retrimitere de mai sus. Pentru securitate, cererile sunt limitate.',
    'sv_SE' => 'Fick du den inte? Kontrollera först skräpposten och använd sedan knappen ovan för att skicka igen. Av säkerhetsskäl är förfrågningar begränsade.',
    'da_DK' => 'Modtog du det ikke? Tjek spam først, og brug derefter knappen ovenfor til at sende igen. Af sikkerhedshensyn er anmodninger begrænset.',
    'fi' => 'Etkö saanut sitä? Tarkista ensin roskaposti ja käytä sitten yllä olevaa uudelleenlähetyspainiketta. Turvallisuussyistä pyyntöjä rajoitetaan.',
    'cs_CZ' => 'Nedorazil? Nejprve zkontrolujte spam a poté použijte tlačítko pro opětovné odeslání. Z bezpečnostních důvodů jsou požadavky omezeny.',
    'cs' => 'Nedorazil? Nejprve zkontrolujte spam a poté použijte tlačítko pro opětovné odeslání. Z bezpečnostních důvodů jsou požadavky omezeny.',
    'sk_SK' => 'Nedorazil? Nejprve zkontrolujte spam a poté použijte tlačítko pro opětovné odeslání. Z bezpečnostních důvodů jsou požadavky omezeny.',
    'sk' => 'Nedorazil? Nejprve zkontrolujte spam a poté použijte tlačítko pro opětovné odeslání. Z bezpečnostních důvodů jsou požadavky omezeny.',
    'hu_HU' => 'Nem kapta meg? Először ellenőrizze a spam mappát, majd használja a fenti újraküldés gombot. Biztonsági okokból a kérések korlátozottak.',
    'hu' => 'Nem kapta meg? Először ellenőrizze a spam mappát, majd használja a fenti újraküldés gombot. Biztonsági okokból a kérések korlátozottak.',
    'el_GR' => 'Δεν το λάβατε; Ελέγξτε πρώτα τα ανεπιθύμητα και μετά χρησιμοποιήστε το κουμπί επανάληψης αποστολής. Για ασφάλεια, τα αιτήματα περιορίζονται.',
    'el' => 'Δεν το λάβατε; Ελέγξτε πρώτα τα ανεπιθύμητα και μετά χρησιμοποιήστε το κουμπί επανάληψης αποστολής. Για ασφάλεια, τα αιτήματα περιορίζονται.',
    'hr' => 'Niste je primili? Najprije provjerite neželjenu poštu, zatim upotrijebite gumb za ponovno slanje. Radi sigurnosti, zahtjevi su ograničeni.',
    'hr_HR' => 'Niste je primili? Najprije provjerite neželjenu poštu, zatim upotrijebite gumb za ponovno slanje. Radi sigurnosti, zahtjevi su ograničeni.',
    'sl_SI' => 'Niste prejeli? Najprej preverite neželeno pošto, nato uporabite zgornji gumb za ponovno pošiljanje. Zaradi varnosti so zahteve omejene.',
    'sl' => 'Niste prejeli? Najprej preverite neželeno pošto, nato uporabite zgornji gumb za ponovno pošiljanje. Zaradi varnosti so zahteve omejene.',
    'no_NO' => 'Mottok du den ikke? Sjekk spam først, og bruk deretter knappen for å sende på nytt. Av sikkerhetshensyn er forespørsler begrenset.',
    'no' => 'Mottok du den ikke? Sjekk spam først, og bruk deretter knappen for å sende på nytt. Av sikkerhetshensyn er forespørsler begrenset.',
    'nb_NO' => 'Mottok du den ikke? Sjekk spam først, og bruk deretter knappen for å sende på nytt. Av sikkerhetshensyn er forespørsler begrenset.',
    'nb' => 'Mottok du den ikke? Sjekk spam først, og bruk deretter knappen for å sende på nytt. Av sikkerhetshensyn er forespørsler begrenset.',
    'is_IS' => 'Fékkstu hann ekki? Athugaðu ruslpóst fyrst og notaðu síðan endursendingarhnappinn. Af öryggisástæðum eru beiðnir takmarkaðar.',
    'is' => 'Fékkstu hann ekki? Athugaðu ruslpóst fyrst og notaðu síðan endursendingarhnappinn. Af öryggisástæðum eru beiðnir takmarkaðar.',
    'ga' => 'Nach bhfuair tú é? Seiceáil dramhphost ar dtús, ansin úsáid an cnaipe athsheolta thuas. Ar mhaithe le slándáil, tá teorainn le hiarratais.',
    'ga_IE' => 'Nach bhfuair tú é? Seiceáil dramhphost ar dtús, ansin úsáid an cnaipe athsheolta thuas. Ar mhaithe le slándáil, tá teorainn le hiarratais.',
    'textarea' => true,
  ),
  'frontend.the_login_link_expires_in_30_minutes_your_account_session_stays_active' => 
  array (
    'group' => 'frontend',
    'label' => 'The login link expires in 30 minutes. Your account session stays active for 1...',
    'default' => 'The login link expires in 30 minutes. Your account session stays active for 14 days after login.',
    'mt_MT' => 'Il-link tal-login tiskadi fi 30 minuta. Is-sessjoni tal-kont tiegħek tibqa’ attiva għal 14-il jum wara l-login.',
    'de_DE' => 'Der Login-Link läuft nach 30 Minuten ab. Ihre Kontositzung bleibt nach dem Login 14 Tage aktiv.',
    'nl_NL' => 'De loginlink verloopt na 30 minuten. Je accountsessie blijft na inloggen 14 dagen actief.',
    'pl_PL' => 'Link logowania wygasa po 30 minutach. Sesja konta pozostaje aktywna przez 14 dni po zalogowaniu.',
    'lt_LT' => 'Prisijungimo nuoroda baigia galioti po 30 minučių. Paskyros sesija po prisijungimo lieka aktyvi 14 dienų.',
    'lv' => 'Pieteikšanās saite beidzas pēc 30 minūtēm. Konta sesija pēc pieteikšanās paliek aktīva 14 dienas.',
    'bg_BG' => 'Връзката за вход изтича след 30 минути. Сесията в профила остава активна 14 дни след вход.',
    'et' => 'Sisselogimislink aegub 30 minutiga. Kontoseanss püsib aktiivne 14 päeva pärast sisselogimist.',
    'fr_FR' => 'Le lien de connexion expire dans 30 minutes. Votre session de compte reste active pendant 14 jours après la connexion.',
    'it_IT' => 'Il link di accesso scade tra 30 minuti. La sessione dell’account resta attiva per 14 giorni dopo l’accesso.',
    'es_ES' => 'El enlace de acceso caduca en 30 minutos. La sesión de tu cuenta permanece activa durante 14 días después de iniciar sesión.',
    'ru_RU' => 'Ссылка для входа действует 30 минут. После входа сессия аккаунта остаётся активной 14 дней.',
    'pt_PT' => 'O link de acesso expira em 30 minutos. A sessão da conta fica ativa por 14 dias após o login.',
