  'frontend.your_booking_was_saved_but_the_payment_attempt_failed_or_could_not_be_' => 
  array (
    'group' => 'frontend',
    'label' => 'Your booking was saved, but the payment attempt failed or could not be starte...',
    'default' => 'Your booking was saved, but the payment attempt failed or could not be started. Please contact the site owner or try another payment method if available.',
    'de_DE' => 'Ihre Buchung wurde gespeichert, aber der Zahlungsversuch ist fehlgeschlagen oder konnte nicht gestartet werden. Bitte kontaktieren Sie den Websitebetreiber oder versuchen Sie eine andere Zahlungsmethode, falls verfügbar.',
    'nl_NL' => 'Je boeking is opgeslagen, maar de betalingspoging is mislukt of kon niet worden gestart. Neem contact op met de site-eigenaar of probeer een andere betaalmethode als die beschikbaar is.',
    'pl_PL' => 'Rezerwacja została zapisana, ale próba płatności nie powiodła się albo nie mogła zostać rozpoczęta. Skontaktuj się z właścicielem strony albo wybierz inną metodę płatności, jeśli jest dostępna.',
    'lt_LT' => 'Jūsų užsakymas išsaugotas, tačiau mokėjimas nepavyko arba jo nepavyko pradėti. Susisiekite su svetainės savininku arba pabandykite kitą mokėjimo būdą, jei jis yra.',
    'lv' => 'Jūsu rezervācija tika saglabāta, bet maksājuma mēģinājums neizdevās vai to nevarēja sākt. Sazinieties ar vietnes īpašnieku vai izmēģiniet citu maksājuma veidu, ja tas ir pieejams.',
    'bg_BG' => 'Резервацията ви беше запазена, но опитът за плащане беше неуспешен или не можа да започне. Свържете се със собственика на сайта или опитайте друг начин на плащане, ако е наличен.',
    'et' => 'Sinu broneering salvestati, kuid maksekatse ebaõnnestus või seda ei saanud alustada. Võta ühendust saidi omanikuga või proovi teist makseviisi, kui see on saadaval.',
    'fr_FR' => 'Votre réservation a été enregistrée, mais la tentative de paiement a échoué ou n’a pas pu démarrer. Contactez le propriétaire du site ou essayez un autre moyen de paiement, s’il est disponible.',
    'it_IT' => 'La prenotazione è stata salvata, ma il tentativo di pagamento non è riuscito o non è stato possibile avviarlo. Contatta il proprietario del sito oppure prova un altro metodo di pagamento, se disponibile.',
    'es_ES' => 'Tu reserva se guardó, pero el intento de pago falló o no pudo iniciarse. Ponte en contacto con el propietario del sitio o prueba otro método de pago si está disponible.',
    'ru_RU' => 'Бронирование сохранено, но попытка оплаты не удалась или не была запущена. Свяжитесь с владельцем сайта или выберите другой способ оплаты, если он доступен.',
    'pt_PT' => 'A sua reserva foi guardada, mas a tentativa de pagamento falhou ou não pôde ser iniciada. Contacte o proprietário do site ou tente outro método de pagamento, se disponível.',
    'pt_BR' => 'A sua reserva foi guardada, mas a tentativa de pagamento falhou ou não pôde ser iniciada. Contacte o proprietário do site ou tente outro método de pagamento, se disponível.',
    'ro_RO' => 'Rezervarea a fost salvată, dar încercarea de plată a eșuat sau nu a putut fi pornită. Contactați proprietarul site-ului sau încercați altă metodă de plată, dacă este disponibilă.',
    'sv_SE' => 'Din bokning sparades, men betalningsförsöket misslyckades eller kunde inte startas. Kontakta webbplatsägaren eller försök med en annan betalningsmetod om tillgänglig.',
    'da_DK' => 'Din booking blev gemt, men betalingsforsøget mislykkedes eller kunne ikke startes. Kontakt sideejeren eller prøv en anden betalingsmetode, hvis muligt.',
    'fi' => 'Varaus tallennettiin, mutta maksuyritys epäonnistui tai sitä ei voitu aloittaa. Ota yhteyttä sivuston omistajaan tai kokeile toista maksutapaa, jos saatavilla.',
    'cs_CZ' => 'Vaše rezervace byla uložena, ale pokus o platbu selhal nebo se nepodařilo jej spustit. Kontaktujte majitele webu nebo zkuste jiný způsob platby, pokud je k dispozici.',
    'cs' => 'Vaše rezervace byla uložena, ale pokus o platbu selhal nebo se nepodařilo jej spustit. Kontaktujte majitele webu nebo zkuste jiný způsob platby, pokud je k dispozici.',
    'sk_SK' => 'Vaše rezervace byla uložena, ale pokus o platbu selhal nebo se nepodařilo jej spustit. Kontaktujte majitele webu nebo zkuste jiný způsob platby, pokud je k dispozici.',
    'sk' => 'Vaše rezervace byla uložena, ale pokus o platbu selhal nebo se nepodařilo jej spustit. Kontaktujte majitele webu nebo zkuste jiný způsob platby, pokud je k dispozici.',
    'hu_HU' => 'A foglalás mentve lett, de a fizetési kísérlet sikertelen volt vagy nem indult el. Lépjen kapcsolatba a webhely tulajdonosával, vagy próbáljon más fizetési módot, ha elérhető.',
    'hu' => 'A foglalás mentve lett, de a fizetési kísérlet sikertelen volt vagy nem indult el. Lépjen kapcsolatba a webhely tulajdonosával, vagy próbáljon más fizetési módot, ha elérhető.',
    'el_GR' => 'Η κράτησή σας αποθηκεύτηκε, αλλά η προσπάθεια πληρωμής απέτυχε ή δεν μπόρεσε να ξεκινήσει. Επικοινωνήστε με τον ιδιοκτήτη του ιστότοπου ή δοκιμάστε άλλη μέθοδο πληρωμής αν είναι διαθέσιμη.',
    'el' => 'Η κράτησή σας αποθηκεύτηκε, αλλά η προσπάθεια πληρωμής απέτυχε ή δεν μπόρεσε να ξεκινήσει. Επικοινωνήστε με τον ιδιοκτήτη του ιστότοπου ή δοκιμάστε άλλη μέθοδο πληρωμής αν είναι διαθέσιμη.',
    'hr' => 'Vaša je rezervacija spremljena, ali pokušaj plaćanja nije uspio ili nije mogao započeti. Kontaktirajte vlasnika stranice ili pokušajte drugi način plaćanja ako je dostupan.',
    'hr_HR' => 'Vaša je rezervacija spremljena, ali pokušaj plaćanja nije uspio ili nije mogao započeti. Kontaktirajte vlasnika stranice ili pokušajte drugi način plaćanja ako je dostupan.',
    'sl_SI' => 'Vaša rezervacija je bila shranjena, vendar poskus plačila ni uspel ali ga ni bilo mogoče začeti. Kontaktirajte lastnika spletnega mesta ali poskusite drug način plačila, če je na voljo.',
    'sl' => 'Vaša rezervacija je bila shranjena, vendar poskus plačila ni uspel ali ga ni bilo mogoče začeti. Kontaktirajte lastnika spletnega mesta ali poskusite drug način plačila, če je na voljo.',
    'no_NO' => 'Bestillingen din ble lagret, men betalingsforsøket mislyktes eller kunne ikke startes. Kontakt nettstedseieren eller prøv en annen betalingsmåte hvis tilgjengelig.',
    'no' => 'Bestillingen din ble lagret, men betalingsforsøket mislyktes eller kunne ikke startes. Kontakt nettstedseieren eller prøv en annen betalingsmåte hvis tilgjengelig.',
    'nb_NO' => 'Bestillingen din ble lagret, men betalingsforsøket mislyktes eller kunne ikke startes. Kontakt nettstedseieren eller prøv en annen betalingsmåte hvis tilgjengelig.',
    'nb' => 'Bestillingen din ble lagret, men betalingsforsøket mislyktes eller kunne ikke startes. Kontakt nettstedseieren eller prøv en annen betalingsmåte hvis tilgjengelig.',
    'is_IS' => 'Bókunin þín var vistuð, en greiðslutilraunin mistókst eða gat ekki hafist. Hafðu samband við eiganda síðunnar eða prófaðu aðra greiðslumáta ef þeir eru tiltækir.',
    'is' => 'Bókunin þín var vistuð, en greiðslutilraunin mistókst eða gat ekki hafist. Hafðu samband við eiganda síðunnar eða prófaðu aðra greiðslumáta ef þeir eru tiltækir.',
    'ga' => 'Sábháladh d’áirithint, ach theip ar an iarracht íocaíochta nó níorbh fhéidir í a thosú. Déan teagmháil le húinéir an tsuímh nó bain triail as modh íocaíochta eile má tá sé ar fáil.',
    'ga_IE' => 'Sábháladh d’áirithint, ach theip ar an iarracht íocaíochta nó níorbh fhéidir í a thosú. Déan teagmháil le húinéir an tsuímh nó bain triail as modh íocaíochta eile má tá sé ar fáil.',
    'textarea' => true,
    'mt_MT' => 'Il-prenotazzjoni tiegħek ġiet salvata, iżda t-tentattiv tal-ħlas falla jew ma setax jinbeda. Ikkuntattja lis-sid tas-sit jew ipprova metodu ieħor ta’ ħlas jekk ikun disponibbli.',
  ),
  'frontend.your_booking_has_been_received_successfully_a_confirmation_email_will_' => 
  array (
    'group' => 'frontend',
    'label' => 'Your booking has been received successfully. A confirmation email will be sen...',
    'default' => 'Your booking has been received successfully. A confirmation email will be sent to you if email notifications are enabled.',
    'mt_MT' => 'Il-prenotazzjoni tiegħek waslet b’suċċess. Tintbagħatlek email ta’ konferma jekk in-notifiki bl-email huma attivati.',
    'de_DE' => 'Ihre Buchung wurde erfolgreich empfangen. Eine Bestätigungs-E-Mail wird an Sie gesendet, wenn E-Mail-Benachrichtigungen aktiviert sind.',
    'nl_NL' => 'Je boeking is succesvol ontvangen. Er wordt een bevestigingsmail naar je gestuurd als e-mailmeldingen zijn ingeschakeld.',
    'pl_PL' => 'Rezerwacja została pomyślnie przyjęta. E-mail z potwierdzeniem zostanie wysłany, jeśli powiadomienia e-mail są włączone.',
    'lt_LT' => 'Jūsų užsakymas sėkmingai gautas. Jei el. pašto pranešimai įjungti, gausite patvirtinimo laišką.',
    'lv' => 'Jūsu rezervācija ir veiksmīgi saņemta. Ja e-pasta paziņojumi ir iespējoti, jums tiks nosūtīts apstiprinājuma e-pasts.',
    'bg_BG' => 'Вашата резервация беше получена успешно. Ще ви бъде изпратен имейл за потвърждение, ако имейл известията са включени.',
    'et' => 'Sinu broneering on edukalt vastu võetud. Kui e-posti teavitused on lubatud, saadetakse sulle kinnitusmeil.',
    'fr_FR' => 'Votre réservation a bien été reçue. Un e-mail de confirmation vous sera envoyé si les notifications par e-mail sont activées.',
    'it_IT' => 'La prenotazione è stata ricevuta correttamente. Se le notifiche email sono abilitate, ti verrà inviata un’email di conferma.',
    'es_ES' => 'Tu reserva se ha recibido correctamente. Recibirás un correo de confirmación si las notificaciones por correo electrónico están activadas.',
    'ru_RU' => 'Ваше бронирование успешно получено. Если email-уведомления включены, вы получите письмо с подтверждением.',
    'pt_PT' => 'A sua reserva foi recebida com sucesso. Será enviado um email de confirmação se as notificações por email estiverem ativadas.',
    'pt_BR' => 'A sua reserva foi recebida com sucesso. Será enviado um email de confirmação se as notificações por email estiverem ativadas.',
    'ro_RO' => 'Rezervarea dvs. a fost primită cu succes. Un e-mail de confirmare va fi trimis dacă notificările prin e-mail sunt activate.',
    'sv_SE' => 'Din bokning har tagits emot. Ett bekräftelsemejl skickas om e-postaviseringar är aktiverade.',
    'da_DK' => 'Din booking er modtaget. En bekræftelsesmail sendes, hvis e-mailnotifikationer er aktiveret.',
    'fi' => 'Varaus on vastaanotettu onnistuneesti. Vahvistussähköposti lähetetään, jos sähköposti-ilmoitukset ovat käytössä.',
    'cs_CZ' => 'Vaše rezervace byla úspěšně přijata. Pokud jsou zapnutá e-mailová oznámení, bude vám odeslán potvrzovací e-mail.',
    'cs' => 'Vaše rezervace byla úspěšně přijata. Pokud jsou zapnutá e-mailová oznámení, bude vám odeslán potvrzovací e-mail.',
    'sk_SK' => 'Vaša rezervácia bola úspešne prijatá. Ak sú e-mailové oznámenia zapnuté, bude vám odoslaný potvrdzovací e-mail.',
